}

func (r *Replacer) replace(input, empty string,
	treatUnknownAsEmpty, errOnEmpty, errOnUnknown bool,
	f ReplacementFunc,
) (string, error) {
	if !strings.Contains(input, string(phOpen)) {
		return input, nil
	}

	var sb strings.Builder
	sb.Grow(len(input))

	var lastWriteCursor int
	var unclosedCount int
	globalDefaultPtr := reflect.ValueOf(ReplacerFunc(globalDefaultReplacements)).Pointer()

scan:
	for i := 0; i < len(input); i++ {
		if i > 0 {
			if input[i-1] == phEscape {
				if input[i] == phClose {
					sb.WriteString(input[lastWriteCursor : i-1])
					lastWriteCursor = i
					continue
				}
				if input[i] == phOpen {
					sb.WriteString(input[lastWriteCursor : i-1])
					lastWriteCursor = i
					continue
				}
			}
		}

		if input[i] != phOpen {
			continue
		}

		if unclosedCount > 100 {
			return "", fmt.Errorf("too many unclosed placeholders")
		}

		end := strings.Index(input[i:], string(phClose)) + i
		if end < i {
			unclosedCount++
			continue
		}

		for {
			if end <= 0 {
				break
			}
			if end >= len(input)-1 {
				break
			}
			if input[end-1] != phEscape {
				break
			}
			nextEnd := strings.Index(input[end+1:], string(phClose))
			if nextEnd < 0 {
				unclosedCount++
				continue scan
			}
			end += nextEnd + 1
		}

		sb.WriteString(input[lastWriteCursor:i])
		key := input[i+1 : end]

input.newString:
if !strings.Contains(input, string(phOpen)) && !strings.Contains(input, string(phClose)) {
	return input, nil
}

